import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    p = [0] * (n + 2)
    p[0] = n + 1
    for k in range(1, 2 * n + 1, 2):
        p[data[k]] = data[k + 1]

    # The chosen anchors are exactly the isolated balls of the final set.
    # Consecutive anchors delimit independent rectangular gaps, each of
    # which must contain no isolated ball.
    dp = [0] * (n + 2)
    dp[0] = 1
    for j in range(1, n + 2):
        low = p[j]
        total = 0
        for i in range(j):
            high = p[i]
            if high <= low or dp[i] == 0:
                continue

            points = []
            minimum = n + 2
            for k in range(i + 1, j):
                value = p[k]
                if low < value < high:
                    points.append((value, minimum))
                    if value < minimum:
                        minimum = value

            maximum = -1
            valid = True
            for value, left_minimum in reversed(points):
                if left_minimum > value and maximum < value:
                    valid = False
                    break
                if value > maximum:
                    maximum = value
            if valid:
                total += dp[i]
        dp[j] = total % MOD

    print(dp[-1])

if __name__ == '__main__':
    main()

