import sys

MOD = 998244353

def main():
    data = iter(map(int, sys.stdin.buffer.read().split()))
    n = next(data)
    m = next(data)
    constraints = [[] for _ in range(n)]
    for _ in range(m):
        l = next(data) - 1
        r = next(data) - 1
        x = next(data) - 1
        constraints[l].append((x, r))

    inv = [0] * (n + 1)
    inv[1] = 1
    for i in range(2, n + 1):
        inv[i] = MOD - (MOD // i) * inv[MOD % i] % MOD

    # dp[l][r] counts valid relative orders on [l,r), divided by (r-l)!.
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        dp[i][i] = 1

    # For a possible maximum at x, the interval's exclusive right endpoint
    # must not exceed bound[x].
    bound = [n] * n
    for l in range(n - 1, -1, -1):
        for x, r in constraints[l]:
            if r < bound[x]:
                bound[x] = r
        row = dp[l]
        for r in range(l + 1, n + 1):
            total = 0
            for k in range(l, r):
                if r <= bound[k]:
                    total += row[k] * dp[k + 1][r]
            row[r] = total % MOD * inv[r - l] % MOD

    answer = dp[0][n]
    for i in range(2, n + 1):
        answer = answer * i % MOD
    print(answer)

