import sys
from collections import deque

MOD = 998244353


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[:2]
    a = [v - 1 for v in data[2:]]
    deg = [0] * n
    for v in a:
        deg[v] += 1

    q = deque(i for i in range(n) if deg[i] == 0)
    dp = [None] * n

    # Remove trees, propagating counts indexed by the parent's value.
    while q:
        v = q.popleft()
        row = dp[v]
        dp[v] = None
        if row is None:
            row = list(range(1, m + 1))
        else:
            s = 0
            for j in range(m):
                s = (s + row[j]) % MOD
                row[j] = s

        p = a[v]
        other = dp[p]
        if other is None:
            dp[p] = row
        else:
            for j in range(m):
                other[j] = other[j] * row[j] % MOD
        deg[p] -= 1
        if deg[p] == 0:
            q.append(p)

    # All vertices on a cycle must have the same value.
    ans = 1
    for v in range(n):
        if deg[v] == 0:
            continue
        row = None
        u = v
        while deg[u]:
            deg[u] = 0
            other = dp[u]
            dp[u] = None
            if other is not None:
                if row is None:
                    row = other
                else:
                    for j in range(m):
                        row[j] = row[j] * other[j] % MOD
            u = a[u]
        ans = ans * (m if row is None else sum(row) % MOD) % MOD

    print(ans)


if __name__ == '__main__':
    main()

