import sys

MOD = 998244353


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    spf = list(range(1001))
    for p in range(2, 32):
        if spf[p] == p:
            for x in range(p * p, 1001, p):
                if spf[x] == x:
                    spf[x] = p

    events = {}
    for i, x in enumerate(data[1:], 1):
        while x > 1:
            p = spf[x]
            e = 0
            while x % p == 0:
                x //= p
                e += 1
            events.setdefault(p, []).append((i, e))

    answer = 1
    for p, ev in events.items():
        total = sum(e for _, e in ev)
        powers = [1] * (total + 1)
        for h in range(1, total + 1):
            powers[h] = powers[h - 1] * p % MOD

        dp = [1]
        for k, (i, e) in enumerate(ev):
            next_i = ev[k + 1][0] if k + 1 < len(ev) else n
            gap = next_i - i
            size = len(dp) + e
            if gap == 1:
                pw = powers
            else:
                base = pow(p, gap, MOD)
                pw = [1] * size
                for h in range(1, size):
                    pw[h] = pw[h - 1] * base % MOD

            nd = [0] * size
            for h, value in enumerate(dp):
                if not value:
                    continue
                j = h + e
                nd[j] = (nd[j] + value * pw[j]) % MOD
                if h >= e:
                    j = h - e
                    nd[j] = (nd[j] + value * pw[j]) % MOD
                else:
                    nd[0] = (nd[0] + value * pow(p, (e - h) * i, MOD)) % MOD
            dp = nd
        answer = answer * sum(dp) % MOD

    print(answer)


if __name__ == '__main__':
    main()

