import sys
from math import gcd


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, budget = data[:2]
    machines = []
    upper = 10**30
    for k in range(n):
        a, p, b, q = data[2 + 4*k:6 + 4*k]
        if a*q < b*p:
            a, p, b, q = b, q, a, p
        machines.append((a, p, b, q, a//gcd(a, b)))
        upper = min(upper, budget*a//p + 1)

    def feasible(w):
        total = 0
        for a, p, b, q, limit in machines:
            best = ((w+a-1)//a)*p
            for j in range(1, min(limit-1, (w+b-1)//b)+1):
                rem = w-j*b
                cost = j*q
                if rem > 0:
                    cost += ((rem+a-1)//a)*p
                if cost < best:
                    best = cost
            total += best
            if total > budget:
                return False
        return True

    low, high = 0, upper
    while high-low > 1:
        mid = (low+high)//2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)


if __name__ == '__main__':
    main()

