class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        mod = 10**9 + 7
        m = len(s)
        depth = [0] * (m + 1)
        for x in range(2, m + 1):
            depth[x] = 1 + depth[x.bit_count()]
        good = [x for x in range(1, m + 1) if depth[x] < k]

        fact = [1] * (m + 1)
        for i in range(1, m + 1):
            fact[i] = fact[i - 1] * i % mod
        inv = [1] * (m + 1)
        inv[m] = pow(fact[m], mod - 2, mod)
        for i in range(m, 0, -1):
            inv[i - 1] = inv[i] * i % mod

        ans = used = 0
        for i, ch in enumerate(s):
            if ch == '1':
                r = m - i - 1
                for target in good:
                    j = target - used
                    if j < 0:
                        continue
                    if j > r:
                        break
                    ans += fact[r] * inv[j] % mod * inv[r - j] % mod
                ans %= mod
                used += 1
        return ans

