def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[0], data[1]
    rows = [0] * n
    for i in range(m):
        u = data[2 + 2 * i] - 1
        v = data[3 + 2 * i] - 1
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    # Reduced row echelon form over GF(2).
    pivots = []
    rank = 0
    for col in range(n):
        bit = 1 << col
        found = -1
        for j in range(rank, n):
            if rows[j] & bit:
                found = j
                break
        if found == -1:
            continue
        rows[rank], rows[found] = rows[found], rows[rank]
        for j in range(n):
            if j != rank and rows[j] & bit:
                rows[j] ^= rows[rank]
        pivots.append(col)
        rank += 1

    pivot_set = set(pivots)
    free = [i for i in range(n) if i not in pivot_set]
    ans = [0] * n
    # Each bit encodes one independent nullspace basis vector.
    for k, col in enumerate(free):
        ans[col] = 1 << k
    for r, col in enumerate(pivots):
        val = 0
        for f in free:
            if rows[r] & (1 << f):
                val ^= ans[f]
        ans[col] = val

    if any(x == 0 for x in ans):
        print('No')
    else:
        print('Yes')
        print(*ans)


