from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        ans = 0
        for dr, dc in ((1, 1), (1, -1), (-1, -1), (-1, 1)):
            er, ec = dc, -dr
            tail = [[1] * m for _ in range(n)]
            rows = range(n - 1, -1, -1) if er == 1 else range(n)
            for r in rows:
                nr = r + er
                if not 0 <= nr < n:
                    continue
                row, nxt = grid[r], grid[nr]
                out, nt = tail[r], tail[nr]
                for c in range(m):
                    nc = c + ec
                    if 0 <= nc < m and nxt[nc] == (0 if row[c] == 2 else 2):
                        out[c] = 1 + nt[nc]

            prev = [0] * m
            rows = range(n) if dr == 1 else range(n - 1, -1, -1)
            for r in rows:
                curr = [0] * m
                pr = r - dr
                row = grid[r]
                for c in range(m):
                    v = row[c]
                    if v == 1:
                        length = 1
                    else:
                        pc = c - dc
                        length = 0
                        if (0 <= pr < n and 0 <= pc < m and prev[pc]
                                and v == (0 if grid[pr][pc] == 2 else 2)):
                            length = prev[pc] + 1
                    curr[c] = length
                    if length:
                        ans = max(ans, length + tail[r][c] - 1)
                prev = curr
        return ans

