class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        powers = [1 % k] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k

        m = (n + 1) // 2
        weights = [
            (powers[i] + powers[n - 1 - i]) % k
            if i != n - 1 - i else powers[i]
            for i in range(m)
        ]

        # dp[i] contains the remainders obtainable using positions i..m-1.
        full = (1 << k) - 1
        dp = [0] * (m + 1)
        dp[m] = 1
        cache = {}
        for i in range(m - 1, -1, -1):
            w, mask = weights[i], dp[i + 1]
            key = (w, mask)
            if key not in cache:
                possible = 0
                for d in range(10):
                    shift = d * w % k
                    possible |= ((mask << shift) | (mask >> (k - shift))) & full
                    if possible == full:
                        break
                cache[key] = possible
            dp[i] = cache[key]

        half = []
        remainder = 0
        for i, w in enumerate(weights):
            for d in range(9, -1 if i else 0, -1):
                r = (remainder + d * w) % k
                if (dp[i + 1] >> ((-r) % k)) & 1:
                    half.append(str(d))
                    remainder = r
                    break

        left = ''.join(half)
        return left + (left[:-1] if n % 2 else left)[::-1]

