import sys
from functools import cmp_to_key


def main():
    it = iter(map(int, sys.stdin.buffer.read().split()))
    n = next(it)
    k = next(it)

    counts = {}
    for _ in range(n):
        pair = (next(it), next(it))
        counts[pair] = counts.get(pair, 0) + 1

    # Functions are listed in the order in which they are applied.
    def compare(f, g):
        return (f[0] - 1) * g[1] - (g[0] - 1) * f[1]

    ordered = sorted(counts, key=cmp_to_key(compare))
    dp = [-1] * (k + 1)
    dp[0] = 1
    seen = 0

    for a, b in ordered:
