import sys
MOD=998244353

def solve(h,w,rows):
    for row in rows:
        if row.count(b'A') & 1:
            return 0
    n=h+w
    parent=list(range(n))
    size=[1]*n
    parity=bytearray(n)
    def find(x):
        v=0
        while parent[x]!=x:
            y=parent[x]
            parity[x]^=parity[y]
            parent[x]=parent[y]
            v^=parity[x]
            x=parent[x]
        return x,v
    cols=bytearray(w)
    components=n
    for i,row in enumerate(rows):
        rp=0
        for j,c in enumerate(row):
            if c==65:
                rp^=1
                cols[j]^=1
            else:
                a,pa=find(i)
                b,pb=find(h+j)
                v=1^rp^cols[j]^pa^pb
                if a==b:
                    if v:
                        return 0
                else:
                    if size[a]<size[b]:
                        a,b=b,a
                    parent[b]=a
                    parity[b]=v
                    size[a]+=size[b]
                    components-=1
    if any(cols):
        return 0
    return pow(2,components,MOD)

