import sys


def solve(n, a, b):
    if a == b:
        return 0
    pos = [i for i, c in enumerate(b) if c == 49]
    if len(pos) > a.count(b'1'):
        return -1
    first = a.find(b'1')
    last = a.rfind(b'1')
    nxt = [n] * (n + 1)
    t = n
    for i in range(n - 1, -1, -1):
        if a[i] == 49:
            t = i
        nxt[i] = t
    gaps = [pos[i] - pos[i - 1] - 1 for i in range(1, len(pos))]

    def feasible(k):
        if first < pos[0] - k:
            return False
        e = first + ((first - pos[0] + k) & 1)
        for idx, z in enumerate(gaps, 1):
            s = e + 1
            if s >= n:
                return False
            if z:
                parity = s & 1
                while True:
                    t = nxt[s] if s >= 0 else first
                    if t >= s + z:
                        break
                    s = t + 1
                    s += (s ^ parity) & 1
                    if s >= n:
                        return False
                s += z
            if s >= n:
                return False
            t = nxt[s] if s >= 0 else first
            if t == n:
                return False
            e = t + ((t - pos[idx] + k) & 1)
        bound = pos[-1] + k
        return e <= bound and last <= bound

    answer = 10**9
    for parity in range(2):
        hi = (n + 1) // 2
        if not feasible(parity + 2 * hi):
            continue
        lo = -1
        while hi - lo > 1:
            mid = (lo + hi) // 2
            if feasible(parity + 2 * mid):
                hi = mid
            else:
                lo = mid
        answer = min(answer, parity + 2 * hi)
    return answer if answer < 10**9 else -1


