import heapq

def main():
    it = iter(map(int, sys.stdin.buffer.read().split()))
    N = next(it)
    W = next(it)
    groups = [[] for _ in range(W + 1)]
    for _ in range(N):
        w = next(it)
        v = next(it)
        if v > 1:
            groups[w].append(1 - v)

    dp = [0] * (W + 1)
    for w in range(1, W + 1):
        heap = groups[w]
        if not heap:
            continue
        heapq.heapify(heap)
        g = [0]
        for _ in range(W // w):
            v = -heap[0]
            if v <= 0:
                break
            g.append(g[-1] + v)
            heapq.heapreplace(heap, 2 - v)
        K = len(g) - 1
        if not K:
            continue
        old = dp
        dp = dp.copy()
        if K <= 4:
            for k in range(1, K + 1):
                z = k * w
                v = g[k]
                for j in range(z, W + 1):
                    value = old[j - z] + v
                    if value > dp[j]:
                        dp[j] = value
        else:
            for r in range(min(w, W - w + 1)):
                a = old[r::w]
                m = len(a)

                def rec(l, h, lo, hi):
                    if l > h:
                        return
                    mid = (l + h) // 2
                    best = -1
                    arg = lo
                    for t in range(max(lo, mid - K), min(mid, hi) + 1):
                        value = a[t] + g[mid - t]
                        if value > best:
                            best = value
                            arg = t
                    dp[r + mid * w] = best
                    rec(l, mid - 1, lo, arg)
                    rec(mid + 1, h, arg, hi)

                rec(1, m - 1, 0, m - 1)
    print(dp[W])

