import sys

def main():
    data = sys.stdin.buffer
    k = int(data.readline())
    s = data.readline().strip()
    t = data.readline().strip()
    n, m = len(s), len(t)
    if abs(n-m) > k:
        print('No')
        return
    offset = k + 1
    size = 2*k + 3
    prev = [-1]*size
    x = 0
    while x < n and x < m and s[x] == t[x]:
        x += 1
    prev[offset] = x
    if x == n and x == m:
        print('Yes')
        return
    for e in range(1, k+1):
        cur = [-1]*size
        for d in range(-e, e+1):
            idx = offset + d
            x = -1
            p = prev[idx]
            if p >= 0 and p < n and p-d < m:
                x = p+1
            p = prev[idx-1]
            if p >= 0 and p < n:
                if p+1 > x:
                    x = p+1
            p = prev[idx+1]
            if p >= 0 and p-d-1 < m:
                if p > x:
                    x = p
            if x < 0:
                continue
            y = x-d
            while x < n and y < m and s[x] == t[y]:
                x += 1
                y += 1
            cur[idx] = x
        if cur[offset+n-m] == n:
            print('Yes')
            return
        prev = cur
    print('No')

