    t = next(data) - 1
    graph = [[] for _ in range(n)]
    for _ in range(m):
        u = next(data) - 1
        v = next(data) - 1
        graph[u].append(v)
        graph[v].append(u)

    def bfs(start):
        dist = [-1] * n
        parent = [-1] * n
        dist[start] = 0
        queue = [start]
        for u in queue:
            nd = dist[u] + 1
            for v in graph[u]:
                if dist[v] == -1:
                    dist[v] = nd
                    parent[v] = u
                    queue.append(v)
        return dist, parent, queue

    ds, parent, order = bfs(s)
    dt, _, _ = bfs(t)
    distance = ds[t]
    label = [-1] * n
    v = t
    while v != -1:
        label[v] = ds[v]
        v = parent[v]
    for v in order:
        if label[v] == -1:
            label[v] = label[parent[v]]

    infinity = 10**18
    answer = infinity
    for v in range(n):
        if len(graph[v]) >= 3:
            first_s = -1
            first_t = -1
            multiple = False
            for u in graph[v]:
                if ds[u] == ds[v] - 1:
                    if first_s != -1:
                        multiple = True
                    first_s = u
                if dt[u] == dt[v] - 1:
                    if first_t != -1:
