from math import gcd

class Solution:
    def maxScore(self, nums: List[int]) -> int:
        best = 0
        for removed in range(-1, len(nums)):
            g, l = 0, 1
            for i, x in enumerate(nums):
                if i != removed:
                    g = gcd(g, x)
                    l = l // gcd(l, x) * x
            best = max(best, g * l)
        return best

