class Solution:
    def lengthAfterTransformations(self, s: str, t: int) -> int:
        mod = 10**9 + 7
        counts = [0] * 26
        for ch in s:
            counts[ord(ch) - ord('a')] += 1

        for _ in range(t):
            z = counts[25]
            counts = [z, (counts[0] + z) % mod] + counts[1:25]

        return sum(counts) % mod

