from typing import List

class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        # Bit s is set when a subset of the processed applicable queries
        # can decrement this index by exactly s.
        dp = [1] * len(nums)
        masks = [(1 << (x + 1)) - 1 for x in nums]
        done = [x == 0 for x in nums]
        remaining = sum(not x for x in done)
        if remaining == 0:
            return 0

        for k, (left, right, value) in enumerate(queries, 1):
            for i in range(left, right + 1):
                if done[i]:
                    continue
                dp[i] = (dp[i] | (dp[i] << value)) & masks[i]
                if (dp[i] >> nums[i]) & 1:
                    done[i] = True
                    remaining -= 1
            if remaining == 0:
                return k
        return -1

