import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        upper = 10 ** len(str(n))
        lower = upper // 10

        prime = bytearray(b'\x01') * upper
        prime[0] = prime[1] = 0
        for p in range(2, int((upper - 1) ** 0.5) + 1):
            if prime[p]:
                start = p * p
                prime[start:upper:p] = b'\x00' * ((upper - 1 - start) // p + 1)

        if prime[n] or prime[m]:
            return -1

        dist = [float('inf')] * upper
        dist[n] = n
        heap = [(n, n)]
        places = []
        p = 1
        while p < upper:
            places.append(p)
            p *= 10

        while heap:
            cost, x = heapq.heappop(heap)
            if cost != dist[x]:
                continue
            if x == m:
                return cost

            for place in places:
                digit = (x // place) % 10
                if digit < 9:
                    y = x + place
                    if not prime[y] and cost + y < dist[y]:
                        dist[y] = cost + y
                        heapq.heappush(heap, (cost + y, y))
                if digit > 0:
                    y = x - place
                    if y >= lower and not prime[y] and cost + y < dist[y]:
                        dist[y] = cost + y
                        heapq.heappush(heap, (cost + y, y))

        return -1

