class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        z = [0] * n
        left = right = 0
        for k in range(1, n):
            v = min(right - k + 1, z[k - left]) if k <= right else 0
            while k + v < n and nums[v] == nums[k + v]:
                v += 1
            z[k] = v
            if k + v - 1 > right:
                left, right = k, k + v - 1
        ans = 0
        for i in range(1, n - 1):
            m = n - i
            limit = m // 2
            if z[i] >= i:
                ans += max(0, n - 2 * i)
                limit = min(limit, i - 1)
            if limit == 0:
                continue
            a = nums[i:]
            zz = [0] * (limit + 1)
            left = right = 0
            for k in range(1, limit + 1):
                v = min(right - k + 1, zz[k - left]) if k <= right else 0
                while k + v < m and a[v] == a[k + v]:
                    v += 1
                zz[k] = v
                if k + v - 1 > right:
                    left, right = k, k + v - 1
                if v >= k:
                    ans += 1
        return ans

