        dp = [0] * (n + 1)
        for i in range(n - 2, 0, -1):
            bound = (n + i) // 2
            if z[i] >= i:
                ans += max(0, n - 2 * i)
                bound = min(bound, 2 * i - 1)
            x = nums[i]
            for j in range(i + 1, n):
                if x == nums[j]:
                    v = dp[j + 1] + 1
                    dp[j] = v
                    if j <= bound and v >= j - i:
