from typing import List

class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        # Paint symmetric pairs, keeping their two colors as the state.
        states = [(a, b) for a in range(3) for b in range(3) if a != b]
        previous = [[j for j, (x, y) in enumerate(states) if x != a and y != b]
                    for a, b in states]
        dp = [cost[0][a] + cost[n - 1][b] for a, b in states]
        for i in range(1, n // 2):
            left, right = cost[i], cost[n - 1 - i]
            dp = [left[a] + right[b] + min(dp[j] for j in previous[k])
                  for k, (a, b) in enumerate(states)]
        return min(dp)

