class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        active = s.count('1')
        previous = 0
        best = 0
        i = 0
        n = len(s)
        while i < n:
            if s[i] == '1':
                i += 1
                continue
            start = i
            while i < n and s[i] == '0':
                i += 1
            length = i - start
            if previous:
                best = max(best, previous + length)
            previous = length
        return active + best

