from typing import List

class Solution:
    def maxRectangleArea(self, points: List[List[int]]) -> int:
        available = set(map(tuple, points))
        best = -1
        for x1, y1 in points:
            for x2, y2 in points:
                if x1 >= x2 or y1 >= y2:
                    continue
                if (x1, y2) not in available or (x2, y1) not in available:
                    continue
                count = sum(x1 <= x <= x2 and y1 <= y <= y2 for x, y in points)
                if count == 4:
                    best = max(best, (x2 - x1) * (y2 - y1))
        return best

